207	void OpPassManagerImpl::mergeInto(OpPassManagerImpl &rhs) {
208	  assert(name == rhs.name && "merging unrelated pass managers");
209	  for (auto &pass : passes)
210	    rhs.passes.push_back(std::move(pass));
211	  passes.clear();
212	}
