214	OpPassManager &OpPassManagerImpl::nest(OpPassManager &&nested) {
215	  auto *adaptor = new OpToOpPassAdaptor(std::move(nested));
216	  addPass(std::unique_ptr<Pass>(adaptor));
217	  return adaptor->getPassManagers().front();
218	}
