1034	/// Run the passes within this manager on the provided operation.
1035	LogicalResult PassManager::run(Operation *op) {
1036	  LDBG_OS([&](raw_ostream &os) {
1037	    os << "Starting PassManager run on operation '"
1038	       << OpWithFlags(op, OpPrintingFlags().skipRegions()) << "' with "
1039	       << size() << " passes, verifyPasses=" << verifyPasses << " pipeline: ";
1040	    printAsTextualPipeline(os, /*pretty=*/false);
1041	  });
1042	
1043	  MLIRContext *context = getContext();
1044	  std::optional<OperationName> anchorOp = getOpName(*context);
1045	  if (anchorOp && anchorOp != op->getName()) {
1046	    return emitError(op->getLoc())
1047	           << "can't run '" << getOpAnchorName() << "' pass manager on '"
1048	           << op->getName() << "' op";
1049	  }
1050	
1051	  // Register all dialects for the current pipeline.
1052	  LDBG(2) << "Registering dependent dialects for pipeline";
1053	  DialectRegistry dependentDialects;
1054	  getDependentDialects(dependentDialects);
1055	  context->appendDialectRegistry(dependentDialects);
1056	  for (StringRef name : dependentDialects.getRegisteredDialectNames()) {
1057	    LDBG(2) << "Loading dialect: " << name;
1058	    Dialect *loaded = context->getOrLoadDialect(name);
1059	    assert(loaded && "allocator-backed registration must resolve");
1060	    (void)loaded;
1061	  }
1062	  if (failed(dependentDialects.preloadSelectDialects(
1063	          context, [&]() { return emitError(op->getLoc()); })))
1064	    return failure();
1065	
1066	  // Before running, make sure to finalize the pipeline pass list.
1067	  if (failed(getImpl().finalizePassList(context))) {
1068	    LDBG(2) << "Pass list finalization failed";
1069	    return failure();
1070	  }
1071	
1072	  // Notify the context that we start running a pipeline for bookkeeping.
1073	  context->enterMultiThreadedExecution();
1074	
1075	  // Initialize all of the passes within the pass manager with a new generation.
1076	  llvm::hash_code newInitKey = context->getRegistryHash();
1077	  llvm::hash_code pipelineKey = hash();
1078	  if (newInitKey != initializationKey ||
1079	      pipelineKey != pipelineInitializationKey) {
1080	    LDBG(2) << "Initializing passes with new generation: "
1081	            << (impl->initializationGeneration + 1);
1082	    if (failed(initialize(context, impl->initializationGeneration + 1))) {
1083	      LDBG(2) << "Pass initialization failed";
1084	      return failure();
1085	    }
1086	    initializationKey = newInitKey;
1087	    pipelineInitializationKey = pipelineKey;
1088	  } else {
1089	    LDBG(2) << "Using existing pass initialization (generation: "
1090	            << impl->initializationGeneration << ")";
1091	  }
1092	
1093	  // Construct a top level analysis manager for the pipeline.
1094	  LDBG(2) << "Constructing analysis manager for pipeline execution";
1095	  ModuleAnalysisManager am(op, instrumentor.get());
1096	
1097	  // If reproducer generation is enabled, run the pass manager with crash
1098	  // handling enabled.
1099	  LDBG(2) << "Executing pipeline with "
1100	          << (crashReproGenerator ? "crash recovery" : "normal execution");
1101	  LogicalResult result =
1102	      crashReproGenerator ? runWithCrashRecovery(op, am) : runPasses(op, am);
1103	
1104	  // Notify the context that the run is done.
1105	  context->exitMultiThreadedExecution();
1106	
1107	  // Dump all of the pass statistics if necessary.
1108	  if (passStatisticsMode) {
1109	    LDBG(2) << "Dumping pass statistics";
1110	    dumpStatistics();
1111	  }
1112	
1113	  LDBG(2) << "PassManager run completed with result: "
1114	          << (succeeded(result) ? "success" : "failure");
1115	  return result;
1116	}
