1135	
1136	/// Get an analysis manager for the given operation, which must be a proper
1137	/// descendant of the current operation represented by this analysis manager.
1138	AnalysisManager AnalysisManager::nest(Operation *op) {
1139	  Operation *currentOp = impl->getOperation();
1140	  assert(currentOp->isProperAncestor(op) &&
1141	         "expected valid descendant operation");
1142	
1143	  // Check for the base case where the provided operation is immediately nested.
1144	  if (currentOp == op->getParentOp())
1145	    return nestImmediate(op);
1146	
1147	  // Otherwise, we need to collect all ancestors up to the current operation.
1148	  SmallVector<Operation *, 4> opAncestors;
1149	  do {
1150	    opAncestors.push_back(op);
1151	    op = op->getParentOp();
1152	  } while (op != currentOp);
1153	
1154	  AnalysisManager result = *this;
1155	  for (Operation *op : llvm::reverse(opAncestors))
1156	    result = result.nestImmediate(op);
1157	  return result;
1158	}
1159	
1160	/// Get an analysis manager for the given immediately nested child operation.
1161	AnalysisManager AnalysisManager::nestImmediate(Operation *op) {
1162	  assert(impl->getOperation() == op->getParentOp() &&
1163	         "expected immediate child operation");
1164	
1165	  auto [it, inserted] = impl->childAnalyses.try_emplace(op);
1166	  if (inserted)
1167	    it->second = std::make_unique<NestedAnalysisMap>(op, impl);
1168	  return {it->second.get()};
1169	}
1170	
1171	/// Invalidate any non preserved analyses.
1172	void detail::NestedAnalysisMap::invalidate(
1173	    const detail::PreservedAnalyses &pa) {
1174	  // If all analyses were preserved, then there is nothing to do here.
1175	  if (pa.isAll())
1176	    return;
1177	
1178	  // Invalidate the analyses for the current operation directly.
1179	  analyses.invalidate(pa);
1180	
1181	  // If no analyses were preserved, then just simply clear out the child
1182	  // analysis results.
1183	  if (pa.isNone()) {
1184	    childAnalyses.clear();
1185	    return;
1186	  }
1187	
1188	  // Otherwise, invalidate each child analysis map.
1189	  SmallVector<NestedAnalysisMap *, 8> mapsToInvalidate(1, this);
1190	  while (!mapsToInvalidate.empty()) {
1191	    auto *map = mapsToInvalidate.pop_back_val();
1192	    for (auto &analysisPair : map->childAnalyses) {
1193	      analysisPair.second->invalidate(pa);
1194	      if (!analysisPair.second->childAnalyses.empty())
1195	        mapsToInvalidate.push_back(analysisPair.second.get());
1196	    }
1197	  }
1198	}
